const header=document.querySelector('[data-header]');const button=document.querySelector('[data-menu-button]');const nav=document.querySelector('[data-nav]');const setHeader=()=>header?.classList.toggle('scrolled',scrollY>12);setHeader();addEventListener('scroll',setHeader,{passive:true});button?.addEventListener('click',()=>{const open=nav.classList.toggle('open');button.setAttribute('aria-expanded',String(open))});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');button?.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());document.querySelectorAll('[data-profile]').forEach(trigger=>trigger.addEventListener('click',()=>document.getElementById(trigger.dataset.profile)?.showModal()));document.querySelectorAll('.profile-dialog').forEach(dialog=>{dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})});const items=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});items.forEach(item=>observer.observe(item));const sections=document.querySelectorAll('main section[id]');const links=[...document.querySelectorAll('.site-nav a[href^="#"]')];const sectionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){links.forEach(link=>link.classList.toggle('active',link.getAttribute('href')===`#${entry.target.id}`))}}),{rootMargin:'-30% 0px -60% 0px'});sections.forEach(section=>sectionObserver.observe(section))}else items.forEach(item=>item.classList.add('visible'));
